"""Hidden behavioral tests for jo: input_file. Generated by pbkit from the gold binary."""


def test_f_obj(run):
    r = run(args=['-f', 'obj.json', 'c=3'], files={'obj.json': b'{"a":1,"b":[1,2]}', 'arr.json': b'[1,2]', 'scalar.json': b'3', 'str.json': b'"x"', 'bad.json': b'{', 'empty.json': b'', 'null.json': b'null', 'dup.json': b'{"a":1,"a":2}', 'nested.json': b'{"field1":123,"field2":"abc"}\n', 'ws.json': b'\n\n {} \n'})
    assert r.stdout == b'{"a":1,"b":[1,2],"c":3}\n'
    assert r.stderr == b''
    assert r.returncode == 0


