    r = run(args=['-f', 'obj.json'], stdin=b'', files={'obj.json': b'{"a":1,"b":[1,2]}', 'arr.json': b'[1,2]', 'scalar.json': b'3', 'str.json': b'"x"', 'bad.json': b'{', 'empty.json': b'', 'null.json': b'null', 'dup.json': b'{"a":1,"a":2}', 'nested.json': b'{"field1":123,"field2":"abc"}\n', 'ws.json': b'\n\n {} \n'})
